#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int p, k;
    std::cin >> p >> k;
    std::vector<bool> visited(p, false);
    int num_groups = 0;
    for (int start = 0; start < p; ++start) {
        if (!visited[start]) {
            num_groups++;
            int r = start;
            while (!visited[r]) {
                visited[r] = true;
                r = static_cast<int>(fmod(r * k, p));
            }
        }
    }
    if (k == 0) {
        num_groups = p;
    } else if (k == 1) {
        num_groups = p + 1;
    }
    long long product = 1;
    const long long MOD = 1000000007;
    for (int i = 0; i < num_groups - 1; ++i) {
        product = (product * p) % MOD;
    }
    std::cout << product << std::endl;
    return 0;
}
